-- Dados de demonstração (is_demo = 1): lotes publicados para o marketplace não começar vazio.
-- Remover depois do lançamento: DELETE FROM questions WHERE lot_id IN (SELECT id FROM lots WHERE is_demo = 1); DELETE FROM lots WHERE is_demo = 1;
INSERT OR IGNORE INTO users (id, name, email, role, seller_status) VALUES
  ('demo-vendedor', 'Vendedores de demonstração', 'demo-vendedor@gadon.com.br', 'vendedor', 'aprovado'),
  ('demo-comprador', 'Comprador de demonstração', 'demo-comprador@gadon.com.br', 'comprador', 'nao_iniciado');


SELECT id, 'demo-comprador', 'Os animais já foram vacinados contra aftosa?', 'Sim, a vacinação está em dia. O comprovante aparece nos documentos da carga.', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-5 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-5 days') FROM lots WHERE is_demo = 1 AND name = 'Nelore selecionado';
SELECT id, 'demo-comprador', 'Qual o prazo para embarque depois da compra?', 'Até 7 dias após a confirmação do pagamento.', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-4 days') FROM lots WHERE is_demo = 1 AND name = 'Nelore selecionado';
SELECT id, 'demo-comprador', 'As fêmeas já foram expostas ao touro?', 'Não. O lote está vazio e pronto para a estação de monta.', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3 days') FROM lots WHERE is_demo = 1 AND name = 'Angus premium';
SELECT id, 'demo-comprador', 'O lote aceita embarque em carreta de dois andares?', 'Sim, o curral tem embarcadouro para carreta de dois andares.', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2 days') FROM lots WHERE is_demo = 1 AND name = 'Cruza industrial';
